import
  std/typetraits,
  eth/common/eth_types_rlp,
  "."/[helpers, state_transition_block]

func readExecutionTransaction(
    txBytes: bellatrix.Transaction): Result[EthTransaction, string] =
  try:
    ok rlp.decode(distinctBase(txBytes), EthTransaction)
  except RlpError as exc:
    err("Invalid transaction: " & exc.msg)

# https://github.com/ethereum/consensus-specs/blob/v1.5.0-alpha.4/specs/deneb/beacon-chain.md#is_valid_versioned_hashes
func is_valid_versioned_hashes*(blck: ForkyBeaconBlock): Result[void, string] =
  static: doAssert typeof(blck).kind >= ConsensusFork.Deneb
  template transactions: untyped = blck.body.execution_payload.transactions
  template commitments: untyped = blck.body.blob_kzg_commitments

  var i = 0
  for txBytes in transactions:
    if txBytes.len == 0 or txBytes[0] != TxEip4844.byte:
      continue  # Only blob transactions may have blobs
    let tx = ? txBytes.readExecutionTransaction()
    for vHash in tx.versionedHashes:
      if commitments.len <= i:
        return err("Extra blobs without matching `blob_kzg_commitments`")
      if vHash != kzg_commitment_to_versioned_hash(commitments[i]):
        return err("Invalid `blob_versioned_hash` at index " & $i)
      inc i
  if i != commitments.len:
    return err("Extra `blob_kzg_commitments` without matching blobs")
  ok()

  # execution payload header
  if not (payload.parent_hash ==
      state.latest_execution_payload_header.block_hash):
    return err("process_execution_payload: payload and state parent hash mismatch")

  # Verify prev_randao
  if not (payload.prev_randao == get_randao_mix(state, get_current_epoch(state))):
    return err("process_execution_payload: payload and state randomness mismatch")

  # Verify timestamp
  if not (payload.timestamp == compute_timestamp_at_slot(state, state.slot)):
    return err("process_execution_payload: invalid timestamp")

  # [New in Deneb] Verify commitments are under limit
  if not (lenu64(body.blob_kzg_commitments) <= cfg.MAX_BLOBS_PER_BLOCK):
    return err("process_execution_payload: too many KZG commitments")

  # Verify the execution payload is valid
  if not notify_new_payload(payload):
    return err("process_execution_payload: execution payload invalid")

  # Cache execution payload header
  state.latest_execution_payload_header = payload.toExecutionPayloadHeader() # [New in Deneb]

  ok()

